<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="color-scheme" content="light dark"><title>Panacea Restaurant · Espacio de trabajo</title>
<style>
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{--bg:#f7f7f2;--surface:#fff;--ink:#183c34;--sub:#72827a;--border:#e4e9e1;--accent:#c46d43;--soft:#eaf2e9;--shadow:0 12px 38px rgba(26,58,44,.04);font-family:'DM Sans',system-ui,sans-serif;background:var(--bg);color:var(--ink)}
*{box-sizing:border-box}body{margin:0}button,input{font:inherit}button{cursor:pointer}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid #e8a66e;outline-offset:2px}a{text-decoration:none;color:inherit}.shell{display:grid;grid-template-columns:258px minmax(0,1fr);min-height:100vh}.sidebar{background:#193e34;color:#eaf1e9;padding:30px 19px;display:flex;flex-direction:column;gap:26px}.logo{display:flex;align-items:center;gap:12px;padding:3px 12px}.mark{width:40px;height:40px;border-radius:13px;background:#d9a177;display:grid;place-items:center;color:#193e34;font-size:26px;font-weight:800}.logo b{font-family:Manrope,sans-serif;font-size:20px;letter-spacing:-1px}.logo small{display:block;font-size:10px;letter-spacing:2.2px;color:#b8c9be;margin-top:2px}.nav-title{color:#9fb8a8;text-transform:uppercase;letter-spacing:1.8px;font-size:10px;padding:0 13px;margin:8px 0}.nav{display:grid;gap:5px}.nav button{width:100%;border:0;background:transparent;color:#c4d6c9;display:flex;align-items:center;text-align:left;gap:13px;border-radius:12px;padding:13px 15px}.nav button.active{background:#e5eee5;color:#183c34;font-weight:700}.nav button:hover:not(.active){background:#295245}.nav .ico{font-size:18px;width:23px;text-align:center}.side-bottom{margin-top:auto;padding:17px;border:1px solid #47685a;border-radius:16px;color:#c3d5c7;font-size:12px;line-height:1.7}.workspace{padding:32px clamp(20px,4vw,66px);max-width:1600px;width:100%;margin:auto}.top{display:flex;align-items:center;justify-content:space-between;gap:15px;border-bottom:1px solid var(--border);padding-bottom:23px}.eyebrow{font-size:11px;letter-spacing:2px;text-transform:uppercase;color:#88958c;font-weight:700}.top-right{display:flex;align-items:center;gap:12px}.live{background:#e4f0e6;color:#28664c;padding:9px 12px;border-radius:99px;font-size:12px;font-weight:700}.avatar{height:39px;width:39px;border-radius:50%;background:#d8e7d9;display:grid;place-items:center;font-weight:800}.headline{display:flex;align-items:end;justify-content:space-between;gap:20px;margin:34px 0 26px}h1,h2,h3{font-family:Manrope,sans-serif;letter-spacing:-1px}h1{font-size:clamp(28px,3vw,42px);margin:8px 0 7px;font-weight:800}h2{font-size:19px;margin:0}p{color:var(--sub);line-height:1.6;margin:7px 0}.btn{border:0;border-radius:11px;padding:12px 17px;font-weight:700;background:var(--ink);color:#fff;display:inline-flex;gap:9px;align-items:center}.btn.secondary{background:#e7ede5;color:var(--ink)}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.metric,.panel{background:var(--surface);border:1px solid var(--border);border-radius:18px;box-shadow:var(--shadow)}.metric{padding:23px;min-height:151px}.metric .kicker{font-size:13px;color:#7a8b80}.metric strong{display:block;font:800 35px Manrope,sans-serif;letter-spacing:-1.5px;margin:16px 0 4px}.metric small{color:#8b9b8e}.accent{color:var(--accent)}.two{display:grid;grid-template-columns:1.5fr 1fr;gap:18px;margin-top:19px}.panel{padding:24px}.panel-header{display:flex;align-items:center;justify-content:space-between;gap:15px;margin-bottom:18px}.hint{font-size:12px;color:#88988e}.list-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:17px 0;border-bottom:1px solid var(--border)}.list-row:last-child{border-bottom:0}.list-row b{font-size:14px}.list-row small{display:block;color:var(--sub);margin-top:5px}.chip{background:#f4ece2;color:#a15f37;padding:7px 10px;border-radius:8px;font-size:11px;font-weight:700}.chip.green{background:#e6f1e8;color:#32664b}.empty{padding:42px 18px;text-align:center;color:#89968c;border:1px dashed #d4dfd4;border-radius:14px}.empty .symbol{font-size:30px;margin-bottom:10px}.empty b{display:block;color:var(--ink)}.empty p{font-size:13px;max-width:320px;margin:7px auto}.section{display:none}.section.active{display:block}.search{background:white;border:1px solid var(--border);padding:12px 15px;border-radius:11px;width:min(100%,320px);color:var(--ink)}.toolbar{display:flex;justify-content:space-between;gap:15px;align-items:center;margin:0 0 20px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;text-align:left;white-space:nowrap}th{font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#87968a;background:#f7f9f5}th,td{padding:15px;border-bottom:1px solid var(--border)}td{font-size:13px}tbody tr:hover{background:#f8faf6}.notice{margin-top:20px;background:#f0f3e9;border:1px solid #dce5d8;border-radius:12px;padding:13px 17px;font-size:12px;color:#617568;line-height:1.6}.mode{border:1px solid #a5b7a7;background:transparent;color:#fff;border-radius:10px;padding:9px}.dark{--bg:#111f1b;--surface:#1b2e27;--ink:#e9f2e9;--sub:#9cb5a6;--border:#355045;--soft:#254236;--shadow:none}.dark .metric small,.dark .hint,.dark .eyebrow{color:#a5baad}.dark .btn{background:#d9a177;color:#173b31}.dark .btn.secondary,.dark .chip.green{background:#315244;color:#eaf3e9}.dark .chip{background:#513b30;color:#f4c7a2}.dark .search{background:#1b2e27;color:#fff}.dark th{background:#263c32;color:#a9bdaf}.dark tbody tr:hover{background:#294237}.dark .empty b{color:#eaf3e9}.dark .notice{background:#21392e;color:#b8cbbc;border-color:#355045}
@media(max-width:1050px){.shell{grid-template-columns:80px minmax(0,1fr)}.sidebar{padding:25px 9px}.logo b,.logo small,.nav-title,.nav button .txt,.side-bottom{display:none}.logo{padding:0;justify-content:center}.nav button{justify-content:center;padding:13px 8px}.metrics{grid-template-columns:repeat(2,1fr)}}@media(max-width:750px){.shell{display:block}.sidebar{padding:12px;display:flex;flex-direction:row;align-items:center;overflow:auto;gap:10px}.logo{flex-shrink:0}.nav{display:flex;gap:4px}.nav button{min-width:45px}.workspace{padding:20px 16px}.two{grid-template-columns:1fr}.headline{align-items:start;flex-direction:column}.top{padding-bottom:15px}}@media(max-width:430px){.metrics{grid-template-columns:1fr 1fr;gap:9px}.metric{padding:16px;min-height:126px}.metric strong{font-size:27px}.top-right .live{font-size:10px}}
</style></head><body>
<div class="shell"><aside class="sidebar"><div class="logo"><div class="mark">✳</div><div><b>panacea</b><small>RESTAURANT</small></div></div><div><div class="nav-title">ESPACIO DE TRABAJO</div><nav class="nav" aria-label="Módulos">
<button class="active" data-section="resumen"><span class="ico">◈</span><span class="txt">Resumen</span></button>
<button data-section="pedidos"><span class="ico">▤</span><span class="txt">Pedidos</span></button>
<button data-section="cocina"><span class="ico">◫</span><span class="txt">Cocina</span></button>
<button data-section="reservas"><span class="ico">▦</span><span class="txt">Reservas</span></button>
<button data-section="menu"><span class="ico">▧</span><span class="txt">Menú</span></button>
<button data-section="gerencia"><span class="ico">▥</span><span class="txt">Gerencia</span></button>
</nav></div><div class="side-bottom">Panacea Logic AI<br>Entorno local · Datos reales<br><button class="mode" id="themeToggle" type="button">◐ Cambiar tema</button></div></aside>
<main class="workspace"><header class="top"><div class="eyebrow">PANACEA / OPERACIONES</div><div class="top-right"><span class="live">● Base de datos conectada</span><div class="avatar">P</div></div></header>
<section class="section active" id="resumen"><div class="headline"><div><div class="eyebrow">VISTA GENERAL</div><h1>Un buen día empieza aquí.</h1><p>Todo lo importante de tu restaurante, en un solo lugar.</p></div><a class="btn" href="/panacea-operations">Abrir administración ↗</a></div>
<div class="metrics"><article class="metric"><div class="kicker">Pedidos registrados</div><strong>{{ $panaceaData['orders']['count'] }}</strong><small>Base de datos</small></article><article class="metric"><div class="kicker">Platos en catálogo</div><strong>{{ $panaceaData['menus']['count'] }}</strong><small>Productos registrados</small></article><article class="metric"><div class="kicker">Reservas registradas</div><strong>{{ $panaceaData['reservations']['count'] }}</strong><small>Base de datos</small></article><article class="metric"><div class="kicker">Categorías</div><strong class="accent">{{ $panaceaData['categories']['count'] }}</strong><small>Organización del menú</small></article></div>
<div class="two"><div class="panel"><div class="panel-header"><h2>Pedidos recientes</h2><button class="btn secondary" data-go="pedidos">Ver todos →</button></div><div id="recentOrders"></div></div><div class="panel"><div class="panel-header"><h2>Próximos pasos</h2><span class="hint">Operación</span></div><div class="list-row"><div><b>01 · Configura tu catálogo</b><small>Productos y categorías desde administración</small></div><span class="chip">Menú</span></div><div class="list-row"><div><b>02 · Registra pedidos</b><small>Los nuevos pedidos aparecerán aquí</small></div><span class="chip green">Pedidos</span></div><div class="list-row"><div><b>03 · Gestiona las mesas</b><small>Consulta reservas y disponibilidad</small></div><span class="chip">Reservas</span></div></div></div></section>
@foreach (['pedidos'=>'Pedidos','cocina'=>'Cocina','reservas'=>'Reservas','menu'=>'Menú','gerencia'=>'Gerencia'] as $id=>$name)
<section class="section" id="{{ $id }}"><div class="headline"><div><div class="eyebrow">OPERACIONES / {{ strtoupper($name) }}</div><h1>{{ $name }}</h1><p>{{ ['pedidos'=>'Consulta pedidos registrados y su estado.','cocina'=>'Visualiza las órdenes que requieren preparación.','reservas'=>'Consulta la agenda de reservas del restaurante.','menu'=>'Explora los productos registrados en el catálogo.','gerencia'=>'Indicadores verificables de la base de datos.'][$id] }}</p></div><a class="btn" href="/panacea-operations">Gestionar en administración ↗</a></div><div class="panel"><div class="toolbar"><h2>{{ $name === 'Gerencia' ? 'Resumen de registros' : 'Registros' }}</h2><input class="search" data-search="{{ $id }}" aria-label="Buscar en {{ $name }}" placeholder="Buscar registros..."></div><div id="content-{{ $id }}"></div></div></section>
@endforeach
<div class="notice"><b>Versión de desarrollo local.</b> Las cifras y registros se consultan en MariaDB; no son ejemplos inventados. Esta versión permite explorar, filtrar y navegar. Las modificaciones se realizan por ahora desde el administrador original, mientras implementamos las operaciones propias y su autenticación.</div>
</main></div>
<script>
const data=@json($panaceaData);
const safe=(v)=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const empty=(message)=>'<div class="empty"><div class="symbol">◌</div><b>Sin registros todavía</b><p>'+safe(message)+'</p></div>';
const title=(row,keys)=>keys.map(k=>row[k]).find(v=>v!==undefined&&v!==null)??'—';
function renderTable(key,target,query='',fields=null){const rows=data[key].rows||[];const chosen=(fields||data[key].columns).filter(k=>rows.some(r=>Object.prototype.hasOwnProperty.call(r,k))).slice(0,6);const filtered=rows.filter(r=>Object.values(r).some(v=>String(v??'').toLowerCase().includes(query.toLowerCase())));document.getElementById(target).innerHTML=!filtered.length?empty(rows.length?'No hay coincidencias con tu búsqueda.':'Los datos aparecerán cuando registres información en el sistema.'):'<div class="table-wrap"><table><thead><tr>'+chosen.map(k=>'<th>'+safe(k.replaceAll('_',' '))+'</th>').join('')+'</tr></thead><tbody>'+filtered.map(r=>'<tr>'+chosen.map(k=>'<td>'+safe(r[k])+'</td>').join('')+'</tr>').join('')+'</tbody></table></div><p class="hint">Mostrando hasta 30 registros recientes de '+data[key].count+' en total.</p>'}
function renderRecent(){const rows=data.orders.rows.slice(0,5);document.getElementById('recentOrders').innerHTML=rows.length?rows.map(r=>'<div class="list-row"><div><b>Pedido #'+safe(title(r,['order_id']))+'</b><small>'+safe(title(r,['created_at']))+'</small></div><span class="chip">Estado '+safe(title(r,['status_id']))+'</span></div>').join(''):empty('Los pedidos reales aparecerán aquí automáticamente.')}
function renderGerencia(){document.getElementById('content-gerencia').innerHTML='<div class="metrics">'+['orders','menus','reservations','categories'].map((k,i)=>'<article class="metric"><div class="kicker">'+['Pedidos','Productos','Reservas','Categorías'][i]+'</div><strong>'+data[k].count+'</strong><small>Registros reales</small></article>').join('')+'</div><p class="hint">Los reportes financieros se incorporarán cuando validemos el esquema de importes y estados.</p>'}
renderRecent();renderTable('orders','content-pedidos');renderTable('orders','content-cocina','',['order_id','order_type','status_id','created_at']);renderTable('reservations','content-reservas');renderTable('menus','content-menu');renderGerencia();
function go(id){document.querySelectorAll('.section').forEach(s=>s.classList.toggle('active',s.id===id));document.querySelectorAll('[data-section]').forEach(b=>b.classList.toggle('active',b.dataset.section===id));history.replaceState(null,'','#'+id);window.scrollTo(0,0)}
document.querySelectorAll('[data-section]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.section)));document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.go)));
document.querySelectorAll('[data-search]').forEach(input=>input.addEventListener('input',()=>{const id=input.dataset.search;if(id==='gerencia')return;renderTable(id==='menu'?'menus':id==='reservas'?'reservations':'orders','content-'+id,input.value,id==='cocina'?['order_id','order_type','status_id','created_at']:null)}));
document.getElementById('themeToggle').addEventListener('click',()=>document.documentElement.classList.toggle('dark'));if(['resumen','pedidos','cocina','reservas','menu','gerencia'].includes(location.hash.slice(1)))go(location.hash.slice(1));
</script></body></html>